public class NDXExcelPriceJournalImportController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// DebuC 02.12.24
/// </summary>
/// <returns>ClassDescription</returns>
client server static ClassDescription description()
{
    return '';
}

/// <summary>
/// DebuC 02.12.24
/// </summary>
protected void new()
{
    super(classStr(NDXExcelPriceJournalImportService), methodStr(NDXExcelPriceJournalImportService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// DebuC 02.12.24
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    NDXExcelPriceJournalImportController controller = new NDXExcelPriceJournalImportController();
    if(_args && _args.parmObject())
    {
        if(_args.parmObject() is NDXExcelPriceJournalImportParameter)
        {
            NDXExcelPriceJournalImportParameter initialParameter = _args.parmObject();
            NDXExcelPriceJournalImportContract contract = controller.getDataContractObject();

            contract.parmExcelFileId(initialParameter.parmExcelFileId());
            contract.parmPriceDiscJournalNum(initialParameter.parmPriceDiscJournalNum());
            contract.parmRelation(initialParameter.parmRelation());
            contract.parmAccountRelation(initialParameter.parmAccountRelation());
            contract.parmItemCode(initialParameter.parmItemCode());
            contract.parmAccountCode(initialParameter.parmAccountCode());
            contract.parmFromDate(initialParameter.parmFromDate());
        }
    }
    controller.startOperation();
}
